// Requires: ImageLibrary
//
// SkinMenu - skin sets menu for Rust (uMod / Oxide).
//
// Players open a CUI menu that lets them pick a skin per item category,
// save the selection as a named "set", and apply any saved set to their
// inventory. The menu background and frame PNGs are generated by the
// companion Python / Pillow script (design_generator.py) into the
// `oxide/data/SkinMenu/design/` folder. They are read straight from
// disk and uploaded to the server's FileStorage at plugin load
// (ImageLibrary is only used for the skin / category icon URLs).
//
// Skin catalog modes (configurable):
//   "All"      - every skin in the catalog (includes pending workshop
//                items - can be risky on EAC-strict servers).
//   "Approved" - only skins that Facepunch has approved into the game
//                (safe).
//   "Pending"  - only skins that are still pending approval (use at
//                your own risk).

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Converters;
using Newtonsoft.Json.Linq;
using Oxide.Core;
using Oxide.Core.Plugins;
using Oxide.Game.Rust.Cui;
using UnityEngine;

namespace Oxide.Plugins
{
    [Info("SkinMenu", "Devin", "1.1.0")]
    [Description("Per-player skin set menu with CUI design generated via Python + Pillow.")]
    public class SkinMenu : RustPlugin
    {
        [PluginReference] private Plugin ImageLibrary;

        private const string MainPanel = "skinmenu.main";
        private const string FramePanel = "skinmenu.frame";
        private const string ListPanel = "skinmenu.list";
        private const string PromptPanel = "skinmenu.prompt";

        private const string PermUse = "skinmenu.use";
        private const string PermAdmin = "skinmenu.admin";

        // Inner frame occupies 60% width x 80% height of the screen.
        // Within that frame, 1 unit of x covers 0.6 * 16 = 9.6 visual
        // units and 1 unit of y covers 0.8 * 9 = 7.2 visual units, so
        // to draw a SQUARE inside the frame: height_norm = width_norm
        // * (9.6 / 7.2) = width_norm * 4 / 3.
        private const float FrameSquareYPerX = 9.6f / 7.2f;

        // How many category rows are visible at once in the left column.
        private const int VisibleCategoryRows = 6;

        private readonly Dictionary<ulong, EditorState> _editors = new Dictionary<ulong, EditorState>();
        private readonly Dictionary<string, string> _designPng = new Dictionary<string, string>();

        // -------------------------------------------------------------------
        // Config
        // -------------------------------------------------------------------

        public enum SkinMode { All, Approved, Pending }

        private class PluginConfig
        {
            [JsonProperty("Command to open the menu")]
            public string Command = "skinmenu";

            [JsonProperty("Skin catalog mode (All / Approved / Pending)")]
            [JsonConverter(typeof(StringEnumConverter))]
            public SkinMode Mode = SkinMode.Approved;

            [JsonProperty("How many skins per page in the grid")]
            public int SkinsPerPage = 8;

            [JsonProperty("Auto-apply set on respawn if a set is named 'default'")]
            public bool ApplyDefaultOnRespawn = true;

            [JsonProperty("Apply the picked skin to matching inventory items immediately")]
            public bool ApplyOnPick = true;

            [JsonProperty("Steam Web API key (optional, only required for 'pending'/'all' workshop imports)")]
            public string SteamWebApiKey = string.Empty;

            [JsonProperty("Design image file names (placed in oxide/data/SkinMenu/design/)")]
            public DesignImages Design = new DesignImages();

            public class DesignImages
            {
                [JsonProperty("Main panel background")]
                public string Background = "bg.png";

                [JsonProperty("Skin slot frame")]
                public string SlotFrame = "slot.png";

                [JsonProperty("Selected skin slot frame")]
                public string SlotFrameActive = "slot_active.png";

                [JsonProperty("Generic button background")]
                public string Button = "button.png";

                [JsonProperty("Highlighted button background")]
                public string ButtonHighlight = "button_hl.png";
            }
        }

        private PluginConfig _config;

        protected override void LoadDefaultConfig() => _config = new PluginConfig();

        protected override void LoadConfig()
        {
            base.LoadConfig();
            try
            {
                _config = Config.ReadObject<PluginConfig>() ?? new PluginConfig();
            }
            catch (Exception e)
            {
                PrintError($"Config file is corrupted, resetting to defaults: {e.Message}");
                LoadDefaultConfig();
            }

            if (_config.SkinsPerPage < 1)
            {
                PrintWarning($"SkinsPerPage must be >= 1, got {_config.SkinsPerPage}. Falling back to 8.");
                _config.SkinsPerPage = 8;
            }

            SaveConfig();
        }

        protected override void SaveConfig() => Config.WriteObject(_config);

        // -------------------------------------------------------------------
        // Data
        // -------------------------------------------------------------------

        private class SkinSet
        {
            public string Name;
            public Dictionary<string, ulong> Items = new Dictionary<string, ulong>();
            public long CreatedAt;
            public long UpdatedAt;
        }

        private class PlayerData
        {
            public List<SkinSet> Sets = new List<SkinSet>();
            public string ActiveSet;
        }

        private class CatalogSkin
        {
            public ulong SkinId;
            public string Name;
            public string IconUrl;
            public bool Approved;
        }

        private class CatalogCategory
        {
            public string Shortname;
            public string Display;
            public string Icon;
            public List<CatalogSkin> Skins = new List<CatalogSkin>();
        }

        private class Catalog
        {
            public List<CatalogCategory> Categories = new List<CatalogCategory>();
        }

        private Catalog _catalog;

        private readonly Dictionary<ulong, PlayerData> _playerCache = new Dictionary<ulong, PlayerData>();

        private string DataRoot => Path.Combine(Interface.Oxide.DataDirectory, Name);
        private string DataPlayers => Path.Combine(DataRoot, "players");
        private string DataDesign => Path.Combine(DataRoot, "design");
        private string DataCatalog => Path.Combine(DataRoot, "skins.json");

        private void EnsureDataDirs()
        {
            Directory.CreateDirectory(DataRoot);
            Directory.CreateDirectory(DataPlayers);
            Directory.CreateDirectory(DataDesign);
        }

        private void LoadCatalog()
        {
            if (!File.Exists(DataCatalog))
            {
                _catalog = BuildDefaultCatalog();
                File.WriteAllText(DataCatalog, JsonConvert.SerializeObject(_catalog, Formatting.Indented));
                Puts($"Wrote default catalog to {DataCatalog} - edit and reload to customise.");
                return;
            }

            try
            {
                _catalog = JsonConvert.DeserializeObject<Catalog>(File.ReadAllText(DataCatalog)) ?? BuildDefaultCatalog();
            }
            catch (Exception e)
            {
                PrintError($"Failed to read {DataCatalog}: {e.Message}");
                _catalog = BuildDefaultCatalog();
            }
        }

