        private List<CatalogSkin> FilterSkins(CatalogCategory cat)
        {
            switch (_config.Mode)
            {
                case SkinMode.Approved:
                    return cat.Skins.Where(s => s.Approved).ToList();
                case SkinMode.Pending:
                    return cat.Skins.Where(s => !s.Approved).ToList();
                default:
                    return cat.Skins;
            }
        }

        private string PlayerFile(ulong id) => Path.Combine(DataPlayers, id + ".json");

        private PlayerData LoadPlayer(ulong id)
        {
            if (_playerCache.TryGetValue(id, out var cached)) return cached;

            var file = PlayerFile(id);
            PlayerData data;
            if (File.Exists(file))
            {
                try { data = JsonConvert.DeserializeObject<PlayerData>(File.ReadAllText(file)) ?? new PlayerData(); }
                catch (Exception e) { PrintError($"Bad player file for {id}: {e.Message}"); data = new PlayerData(); }
            }
            else
            {
                data = new PlayerData();
            }

            _playerCache[id] = data;
            return data;
        }

        private void SavePlayer(ulong id)
        {
            if (!_playerCache.TryGetValue(id, out var data)) return;
            File.WriteAllText(PlayerFile(id), JsonConvert.SerializeObject(data, Formatting.Indented));
        }

        // -------------------------------------------------------------------
        // Editor (per-player draft state while menu is open)
        // -------------------------------------------------------------------

        private class EditorState
        {
            public Dictionary<string, ulong> Selection = new Dictionary<string, ulong>();
            public int CategoryIndex;
            public int Page;
            public int CategoryScroll;
            public string EditingSetName;
            public bool RefreshTimerActive;
            public bool MenuOpen;
        }

        // -------------------------------------------------------------------
        // Lifecycle
        // -------------------------------------------------------------------

        private void Init()
        {
            permission.RegisterPermission(PermUse, this);
            permission.RegisterPermission(PermAdmin, this);
            EnsureDataDirs();
            LoadCatalog();
        }

        private void OnServerInitialized()
        {
            if (!string.IsNullOrEmpty(_config.Command))
            {
                cmd.AddChatCommand(_config.Command, this, nameof(CmdMenu));
            }
            LoadDesignAssets();
            RegisterRemoteImages();
        }

        private void Unload()
        {
            foreach (var p in BasePlayer.activePlayerList)
            {
                CloseAll(p);
            }
            foreach (var id in _playerCache.Keys.ToList()) SavePlayer(id);
        }

        private void OnPlayerRespawned(BasePlayer player)
        {
            if (!_config.ApplyDefaultOnRespawn || player == null) return;
            var data = LoadPlayer(player.userID);
            var set = data.Sets.FirstOrDefault(s =>
                string.Equals(s.Name, "default", StringComparison.OrdinalIgnoreCase));
            if (set != null) ApplySetToInventory(player, set);
        }

        // Re-register icons if ImageLibrary is (re)loaded after us.
        private void OnPluginLoaded(Plugin plugin)
        {
            if (plugin?.Name == "ImageLibrary") RegisterRemoteImages();
        }

        // Rust CUI has no native mouse-wheel events, so we hook the
        // hotbar active-slot change instead: rolling the wheel cycles
        // the active hotbar slot one step at a time (with 5 -> 0 / 0
        // -> 5 wrap-around). Multi-step jumps (1-6 key presses) are
        // ignored, so the player can still pick a specific slot
        // without scrolling categories. Wheel direction is forwarded
        // to HandleCategoryScroll (left-hand category list).
        private void OnActiveItemChanged(BasePlayer player, Item oldItem, Item newItem)
        {
            if (player == null) return;
            if (!_editors.TryGetValue(player.userID, out var st) || !st.MenuOpen) return;
            if (!permission.UserHasPermission(player.UserIDString, PermUse)) return;

            int oldSlot = oldItem?.position ?? -1;
            int newSlot = newItem?.position ?? -1;
            if (oldSlot < 0 || newSlot < 0 || oldSlot == newSlot) return;

            int delta = newSlot - oldSlot;
            int dir;
            if (delta == 1 || delta == -5) dir = 1;
            else if (delta == -1 || delta == 5) dir = -1;
            else return; // multi-step change = key press, not wheel

            HandleCategoryScroll(player, dir);
        }

        // -------------------------------------------------------------------
        // Image loading
        // -------------------------------------------------------------------

        // Local PNG files are uploaded straight to FileStorage on the
        // server entity - this is the same path that vanilla CUI uses
        // and avoids "RPC Error in AddUI" caused by stale / wrong CRCs
        // coming back from ImageLibrary's file:// path.
        private void LoadDesignAssets()
        {
            _designPng.Clear();

            var server = FileStorage.server;
            if (server == null)
            {
                PrintWarning("FileStorage.server is null - design assets disabled.");
                return;
            }

            var entity = CommunityEntity.ServerInstance;
            if (entity == null || entity.net == null)
            {
                PrintWarning("CommunityEntity.ServerInstance is unavailable - design assets disabled.");
                return;
            }

            LoadDesignAsset("bg", _config.Design.Background, server, entity);
            LoadDesignAsset("slot", _config.Design.SlotFrame, server, entity);
            LoadDesignAsset("slot_active", _config.Design.SlotFrameActive, server, entity);
            LoadDesignAsset("button", _config.Design.Button, server, entity);
            LoadDesignAsset("button_hl", _config.Design.ButtonHighlight, server, entity);
        }

        private void LoadDesignAsset(string key, string file, FileStorage server, CommunityEntity entity)
        {
            if (string.IsNullOrEmpty(file)) return;
            var full = Path.Combine(DataDesign, file);
            if (!File.Exists(full))
            {
                PrintWarning($"Design file missing: {full} - run design_generator.py.");
                return;
            }

            try
            {
                var bytes = File.ReadAllBytes(full);
                var crc = server.Store(bytes, FileStorage.Type.png, entity.net.ID);
                if (crc != 0) _designPng[key] = crc.ToString();
            }
            catch (Exception e)
            {
                PrintError($"Failed to load design file {full}: {e.Message}");
            }
        }

        private void RegisterRemoteImages()
        {
            if (ImageLibrary == null)
            {
                PrintWarning("ImageLibrary is not loaded - skin and category icons will fall back to colour fills.");
                return;
            }

            foreach (var cat in _catalog.Categories)
            {
                if (!string.IsNullOrEmpty(cat.Icon))
                    ImageLibrary.Call("AddImage", cat.Icon, CategoryImageKey(cat.Shortname), (ulong)0);

                foreach (var skin in cat.Skins)
                {
                    if (string.IsNullOrEmpty(skin.IconUrl)) continue;
                    ImageLibrary.Call("AddImage", skin.IconUrl, SkinImageKey(cat.Shortname, skin.SkinId), (ulong)0);
                }
            }
        }

        private static string SkinImageKey(string shortname, ulong skinId) => $"skin.{shortname}.{skinId}";
        private static string CategoryImageKey(string shortname) => $"cat.{shortname}";

        private string DesignPng(string key) =>
            _designPng.TryGetValue(key, out var id) ? id : null;

        private string RemotePng(string key)
        {
            if (ImageLibrary == null) return null;
            // HasImage avoids returning ImageLibrary's "NO IMAGE FOUND"
            // placeholder while the icon is still downloading.
            try
            {
                var ready = ImageLibrary.Call<bool>("HasImage", key, (ulong)0);
                if (!ready) return null;
            }
            catch (Exception) { /* older ImageLibrary versions */ }
            var result = ImageLibrary.Call<string>("GetImage", key, (ulong)0, false);
            return string.IsNullOrEmpty(result) || result == "0" ? null : result;
        }

        // -------------------------------------------------------------------
        // Commands
        // -------------------------------------------------------------------

        private void CmdMenu(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PermUse))
            {
                player.ChatMessage("You don't have permission to use the skin menu.");
                return;
            }

            OpenMain(player);
        }

        [ConsoleCommand("skinmenu.ui")]
        private void CmdUi(ConsoleSystem.Arg arg)
        {
            var player = arg?.Player();
            if (player == null || !arg.HasArgs(1)) return;
            if (!permission.UserHasPermission(player.UserIDString, PermUse)) return;

            var action = arg.GetString(0);
            switch (action)
            {
                case "close":
                    CloseAll(player);
                    break;

                case "category":
                    HandleCategory(player, arg.GetInt(1, 0));
                    break;

                case "cat.scroll":
                    HandleCategoryScroll(player, arg.GetInt(1, 0));
                    break;

                case "page":
                    HandlePage(player, arg.GetInt(1, 0));
                    break;

                case "pageto":
                    HandlePageTo(player, arg.GetInt(1, 0));
                    break;

                case "pick":
                    HandlePick(player, arg.GetString(1), arg.GetULong(2, 0));
                    break;

                case "create":
                    PromptSetName(player, "Create new set", "create.confirm");
                    break;

                case "create.confirm":
                    HandleCreate(player, JoinFrom(arg, 1));
                    break;

                case "save":
                    HandleSave(player);
                    break;

                case "apply":
                    HandleApply(player);
                    break;

                case "sets":
                    OpenSetList(player);
                    break;

                case "sets.close":
                    CuiHelper.DestroyUi(player, ListPanel);
                    break;

                case "set.load":
                    HandleLoadSet(player, JoinFrom(arg, 1));
                    break;

                case "set.enable":
                    HandleEnableSet(player, JoinFrom(arg, 1));
                    break;

                case "set.delete":
                    HandleDeleteSet(player, JoinFrom(arg, 1));
                    break;

                case "prompt.close":
                    CuiHelper.DestroyUi(player, PromptPanel);
                    break;
            }
        }

        private static string JoinFrom(ConsoleSystem.Arg arg, int start)
        {
            if (arg.Args == null || arg.Args.Length <= start) return string.Empty;
            return string.Join(" ", arg.Args.Skip(start));
        }

        // -------------------------------------------------------------------
        // Menu handlers
        // -------------------------------------------------------------------

        private EditorState Editor(BasePlayer p)
        {
            if (!_editors.TryGetValue(p.userID, out var st))
            {
                st = new EditorState();
                var data = LoadPlayer(p.userID);
                var active = data.Sets.FirstOrDefault(s => s.Name == data.ActiveSet);
                if (active != null)
                {
                    foreach (var kv in active.Items) st.Selection[kv.Key] = kv.Value;
                    st.EditingSetName = active.Name;
                }
                _editors[p.userID] = st;
            }
            return st;
        }

        private void HandleCategory(BasePlayer p, int idx)
        {
            var st = Editor(p);
            st.CategoryIndex = Math.Max(0, Math.Min(idx, _catalog.Categories.Count - 1));
            st.Page = 0;
            EnsureSelectedCategoryVisible(st);
            OpenMain(p);
        }

        private void HandleCategoryScroll(BasePlayer p, int delta)
        {
            var st = Editor(p);
            var maxScroll = Math.Max(0, _catalog.Categories.Count - VisibleCategoryRows);
            st.CategoryScroll = Mathf.Clamp(st.CategoryScroll + delta, 0, maxScroll);
            OpenMain(p);
        }

        private void EnsureSelectedCategoryVisible(EditorState st)
        {
            if (st.CategoryIndex < st.CategoryScroll) st.CategoryScroll = st.CategoryIndex;
            var visible = VisibleCategoryRows;
            if (st.CategoryIndex >= st.CategoryScroll + visible)
                st.CategoryScroll = st.CategoryIndex - visible + 1;
            var maxScroll = Math.Max(0, _catalog.Categories.Count - visible);
            st.CategoryScroll = Mathf.Clamp(st.CategoryScroll, 0, maxScroll);
        }

        // Wheel-driven delta paging: scrolls within the current
        // category and wraps into adjacent categories at the edges.
        // (Used only by OnActiveItemChanged today; the bottom arrows
        //  call HandlePageTo with an absolute index and don't wrap.)
        private void HandlePage(BasePlayer p, int delta)
        {
            var st = Editor(p);
            if (_catalog.Categories.Count == 0) return;
            var perPage = Math.Max(1, _config.SkinsPerPage);
            var skins = FilterSkins(_catalog.Categories[st.CategoryIndex]);
            var maxPage = Math.Max(0, (skins.Count - 1) / perPage);
            var target = st.Page + delta;

            if (target < 0 && st.CategoryIndex > 0)
            {
                st.CategoryIndex--;
                var prevSkins = FilterSkins(_catalog.Categories[st.CategoryIndex]);
                st.Page = Math.Max(0, (prevSkins.Count - 1) / perPage);
                EnsureSelectedCategoryVisible(st);
            }
            else if (target > maxPage && st.CategoryIndex < _catalog.Categories.Count - 1)
            {
                st.CategoryIndex++;
                st.Page = 0;
                EnsureSelectedCategoryVisible(st);
            }
            else
            {
                st.Page = Mathf.Clamp(target, 0, maxPage);
            }
            OpenMain(p);
        }

        // Absolute paging used by the on-screen arrows (IQKits-style):
        // clamps to [0, maxPage] within the current category, no wrap.
        private void HandlePageTo(BasePlayer p, int index)
        {
            var st = Editor(p);
            if (_catalog.Categories.Count == 0) return;
            var perPage = Math.Max(1, _config.SkinsPerPage);
            var skins = FilterSkins(_catalog.Categories[st.CategoryIndex]);
            var maxPage = Math.Max(0, (skins.Count - 1) / perPage);
            st.Page = Mathf.Clamp(index, 0, maxPage);
            OpenMain(p);
        }

        private void HandlePick(BasePlayer p, string shortname, ulong skinId)
        {
            var st = Editor(p);
            st.Selection[shortname] = skinId;
            if (_config.ApplyOnPick) ApplySingleSkin(p, shortname, skinId);
            OpenMain(p);
        }

        // Push a single skin to every matching item the player has on them.
        private void ApplySingleSkin(BasePlayer p, string shortname, ulong skinId)
        {
            if (p == null || p.inventory == null || string.IsNullOrEmpty(shortname)) return;
            foreach (var container in new[] { p.inventory.containerMain, p.inventory.containerBelt, p.inventory.containerWear })
            {
                if (container == null) continue;
                foreach (var item in container.itemList)
                {
                    if (item?.info == null || item.info.shortname != shortname) continue;
                    item.skin = skinId;
                    item.MarkDirty();
                    var held = item.GetHeldEntity();
                    if (held != null)
                    {
                        held.skinID = skinId;
                        held.SendNetworkUpdate();
                    }
                }
            }
        }

        private void HandleCreate(BasePlayer p, string name)
        {
            name = (name ?? string.Empty).Trim();
            if (name.Length == 0) { p.ChatMessage("Set name cannot be empty."); return; }

            var data = LoadPlayer(p.userID);
            if (data.Sets.Any(s => string.Equals(s.Name, name, StringComparison.OrdinalIgnoreCase)))
            {
                p.ChatMessage($"You already have a set named '{name}'.");
                return;
            }

            var st = Editor(p);
            var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            data.Sets.Add(new SkinSet
            {
                Name = name,
                Items = new Dictionary<string, ulong>(st.Selection),
                CreatedAt = now,
                UpdatedAt = now,
            });
            data.ActiveSet = name;
            st.EditingSetName = name;
            SavePlayer(p.userID);

            CuiHelper.DestroyUi(p, PromptPanel);
            p.ChatMessage($"Created skin set '{name}'.");
            OpenMain(p);
        }

        private void HandleSave(BasePlayer p)
        {
            var st = Editor(p);
            if (string.IsNullOrEmpty(st.EditingSetName))
            {
                p.ChatMessage("No active set - press 'Create set' first.");
                return;
            }

            var data = LoadPlayer(p.userID);
            var set = data.Sets.FirstOrDefault(s =>
                string.Equals(s.Name, st.EditingSetName, StringComparison.OrdinalIgnoreCase));
            if (set == null)
            {
                p.ChatMessage($"Set '{st.EditingSetName}' no longer exists.");
                return;
            }

            set.Items = new Dictionary<string, ulong>(st.Selection);
            set.UpdatedAt = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            SavePlayer(p.userID);
            p.ChatMessage($"Saved skin set '{set.Name}'.");
        }

        private void HandleApply(BasePlayer p)
        {
            var st = Editor(p);
            var temp = new SkinSet { Name = st.EditingSetName ?? "<draft>", Items = st.Selection };
            ApplySetToInventory(p, temp);
            p.ChatMessage("Applied current selection to your inventory items.");
        }

        private void HandleLoadSet(BasePlayer p, string name)
        {
            var data = LoadPlayer(p.userID);
            var set = data.Sets.FirstOrDefault(s =>
                string.Equals(s.Name, name, StringComparison.OrdinalIgnoreCase));
            if (set == null) return;

            var st = Editor(p);
            st.Selection = new Dictionary<string, ulong>(set.Items);
            st.EditingSetName = set.Name;
            data.ActiveSet = set.Name;
            SavePlayer(p.userID);
            CuiHelper.DestroyUi(p, ListPanel);
            OpenMain(p);
        }

        private void HandleEnableSet(BasePlayer p, string name)
        {
            var data = LoadPlayer(p.userID);
            var set = data.Sets.FirstOrDefault(s =>
                string.Equals(s.Name, name, StringComparison.OrdinalIgnoreCase));
            if (set == null) return;
            data.ActiveSet = set.Name;
            SavePlayer(p.userID);
            ApplySetToInventory(p, set);
            p.ChatMessage($"Enabled set '{set.Name}'.");
        }

        private void HandleDeleteSet(BasePlayer p, string name)
        {
            var data = LoadPlayer(p.userID);
            var removed = data.Sets.RemoveAll(s =>
                string.Equals(s.Name, name, StringComparison.OrdinalIgnoreCase));
            if (removed > 0)
            {
                if (string.Equals(data.ActiveSet, name, StringComparison.OrdinalIgnoreCase))
                    data.ActiveSet = null;
                SavePlayer(p.userID);
                p.ChatMessage($"Deleted set '{name}'.");
            }
            OpenSetList(p);
        }

        // -------------------------------------------------------------------
        // Inventory apply
        // -------------------------------------------------------------------

        private void ApplySetToInventory(BasePlayer p, SkinSet set)
        {
            if (p == null || p.inventory == null || set == null) return;

            foreach (var container in new[] { p.inventory.containerMain, p.inventory.containerBelt, p.inventory.containerWear })
            {
                if (container == null) continue;
                foreach (var item in container.itemList)
                {
                    if (item == null || item.info == null) continue;
                    if (!set.Items.TryGetValue(item.info.shortname, out var skin)) continue;

                    item.skin = skin;
                    item.MarkDirty();
                    var held = item.GetHeldEntity();
                    if (held != null)
                    {
                        held.skinID = skin;
                        held.SendNetworkUpdate();
                    }
                }
            }
        }

