        private const string ColAccent = "0.18 0.56 0.88 1";
        private const string ColAccentSoft = "0.18 0.56 0.88 0.7";
        private const string ColPanel = "0.12 0.13 0.16 0.95";
        private const string ColSlot = "0.16 0.17 0.20 0.95";
        private const string ColRow = "0.18 0.19 0.22 0.95";
        private const string ColDanger = "0.70 0.18 0.18 0.95";
        private const string ColSuccess = "0.20 0.62 0.32 0.95";
        private const string ColTransparent = "0 0 0 0";

        private static string Coord(float x, float y) =>
            x.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture) + " " +
            y.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);

        private void AddStyledButton(CuiElementContainer elements, string parent,
            string text, string command,
            float xMin, float yMin, float xMax, float yMax,
            bool highlighted = false, string altColor = null, int fontSize = 13)
        {
            var pngKey = highlighted ? "button_hl" : "button";
            var png = DesignPng(pngKey);

            // When a custom design PNG is present, draw the PNG first
            // and put the button overlay on top as a transparent click
            // target so the design shows through.
            string buttonColor;
            if (!string.IsNullOrEmpty(png))
            {
                elements.Add(new CuiElement
                {
                    Parent = parent,
                    Components =
                    {
                        new CuiRawImageComponent { Png = png, Color = "1 1 1 1" },
                        new CuiRectTransformComponent
                        {
                            AnchorMin = Coord(xMin, yMin),
                            AnchorMax = Coord(xMax, yMax),
                        }
                    }
                });
                buttonColor = altColor ?? ColTransparent;
            }
            else
            {
                buttonColor = altColor ?? (highlighted ? ColAccent : "0.22 0.23 0.26 0.95");
            }

            elements.Add(new CuiButton
            {
                Button = { Color = buttonColor, Command = command },
                Text = { Text = text ?? string.Empty, FontSize = fontSize,
                         Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                RectTransform =
                {
                    AnchorMin = Coord(xMin, yMin),
                    AnchorMax = Coord(xMax, yMax),
                },
            }, parent);
        }

        private void AddRawImage(CuiElementContainer elements, string parent, string png,
                                 float xMin, float yMin, float xMax, float yMax)
        {
            if (string.IsNullOrEmpty(png)) return;
            elements.Add(new CuiElement
            {
                Parent = parent,
                Components =
                {
                    new CuiRawImageComponent { Png = png, Color = "1 1 1 1" },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = Coord(xMin, yMin),
                        AnchorMax = Coord(xMax, yMax),
                    }
                }
            });
        }

        // -------------------------------------------------------------------
        // Main menu
        // -------------------------------------------------------------------

        private void CloseAll(BasePlayer p)
        {
            CuiHelper.DestroyUi(p, MainPanel);
            CuiHelper.DestroyUi(p, ListPanel);
            CuiHelper.DestroyUi(p, PromptPanel);
            if (_editors.TryGetValue(p.userID, out var st)) st.MenuOpen = false;
            _editors.Remove(p.userID);
        }

        // Returns true if at least one icon needed by the currently-open
        // menu is still loading via ImageLibrary.
        private bool AnyRequiredIconMissing(CatalogCategory cat, List<CatalogSkin> skins)
        {
            if (ImageLibrary == null) return false;

            foreach (var c in _catalog.Categories)
            {
                if (string.IsNullOrEmpty(c.Icon)) continue;
                if (RemotePng(CategoryImageKey(c.Shortname)) == null) return true;
            }

            foreach (var s in skins)
            {
                if (string.IsNullOrEmpty(s.IconUrl)) continue;
                if (RemotePng(SkinImageKey(cat.Shortname, s.SkinId)) == null) return true;
            }
            return false;
        }

        private void OpenMain(BasePlayer p)
        {
            CuiHelper.DestroyUi(p, MainPanel);

            var st = Editor(p);
            if (_catalog.Categories.Count == 0)
            {
                p.ChatMessage("Skin catalog is empty - edit data/SkinMenu/skins.json on the server.");
                return;
            }

            st.CategoryIndex = Mathf.Clamp(st.CategoryIndex, 0, _catalog.Categories.Count - 1);
            var category = _catalog.Categories[st.CategoryIndex];
            var skins = FilterSkins(category);
            var perPage = Math.Max(1, _config.SkinsPerPage);
            var totalPages = Math.Max(1, (int)Math.Ceiling(skins.Count / (double)perPage));
            st.Page = Mathf.Clamp(st.Page, 0, totalPages - 1);

            EnsureSelectedCategoryVisible(st);

            var elements = new CuiElementContainer();
            BuildOverlay(elements);
            BuildFrame(elements);
            BuildHeader(elements, category, st.Page, totalPages);
            BuildCategoryColumn(elements, st);
            BuildSkinGrid(elements, category, skins, st, perPage, totalPages);
            BuildActionButtons(elements, st);
            BuildBottomPager(elements, st, totalPages);
            BuildFooter(elements);

            CuiHelper.AddUi(p, elements);
            st.MenuOpen = true;

            // Auto-refresh the menu once ImageLibrary has fetched any
            // icons that weren't ready on first render. Guard flag
            // prevents timer pile-ups when the player clicks around
            // while icons are still downloading.
            if (!st.RefreshTimerActive && AnyRequiredIconMissing(category, skins))
            {
                st.RefreshTimerActive = true;
                var userId = p.userID;
                timer.Once(2f, () =>
                {
                    if (!_editors.TryGetValue(userId, out var current)) return;
                    current.RefreshTimerActive = false;
                    if (!current.MenuOpen) return;
                    var bp = BasePlayer.FindByID(userId);
                    if (bp != null && bp.IsConnected) OpenMain(bp);
                });
            }
        }

