        // Left of the menu: a tiny scrollbar strip (up / down arrows)
        // plus the category list. Rows have a fixed height so they
        // stay compact regardless of how many categories exist.
        private void BuildCategoryColumn(CuiElementContainer elements, EditorState st)
        {
            const float scrollLeft = 0.02f;
            const float scrollRight = 0.06f;
            const float catsLeft = 0.07f;
            const float catsRight = 0.30f;
            const float top = 0.90f;
            const float bot = 0.30f;

            var total = _catalog.Categories.Count;
            var visible = Mathf.Min(VisibleCategoryRows, Mathf.Max(1, total));
            var maxScroll = Math.Max(0, total - visible);
            st.CategoryScroll = Mathf.Clamp(st.CategoryScroll, 0, maxScroll);

            BuildCategoryScrollbar(elements, st, total, visible,
                scrollLeft, scrollRight, top, bot);

            // Wrapper panel for the list itself (helps with relative
            // rect math + gives the column its background colour).
            elements.Add(new CuiPanel
            {
                Image = { Color = ColSlot },
                RectTransform =
                {
                    AnchorMin = Coord(catsLeft, bot),
                    AnchorMax = Coord(catsRight, top),
                },
            }, FramePanel, FramePanel + ".cats");

            if (total == 0) return;

            const float headerH = 0.06f;
            elements.Add(new CuiLabel
            {
                Text =
                {
                    Text = "Categories", FontSize = 11,
                    Align = TextAnchor.MiddleCenter, Color = "0.85 0.85 0.85 1",
                },
                RectTransform =
                {
                    AnchorMin = $"0 {1f - headerH}",
                    AnchorMax = "1 1",
                },
            }, FramePanel + ".cats");

            var listTop = 1f - headerH - 0.01f;
            // Fixed row height (in cats-panel-normalized y units). Keeps
            // cards compact even when there are only 2-3 categories.
            var rowH = (listTop - 0.02f) / VisibleCategoryRows;

            for (var slot = 0; slot < visible; slot++)
            {
                var i = st.CategoryScroll + slot;
                if (i >= total) break;

                var rowTop = listTop - slot * rowH;
                var rowBot = rowTop - rowH + 0.008f;
                var rowName = FramePanel + ".cats.row" + slot;
                var active = i == st.CategoryIndex;

                var card = DesignPng(active ? "slot_active" : "slot");
                if (!string.IsNullOrEmpty(card))
                {
                    elements.Add(new CuiElement
                    {
                        Parent = FramePanel + ".cats",
                        Name = rowName,
                        Components =
                        {
                            new CuiRawImageComponent { Png = card, Color = "1 1 1 1" },
                            new CuiRectTransformComponent
                            {
                                AnchorMin = $"0.04 {rowBot}",
                                AnchorMax = $"0.96 {rowTop}",
                            }
                        }
                    });
                }
                else
                {
                    elements.Add(new CuiPanel
                    {
                        Image = { Color = active ? ColAccentSoft : ColRow },
                        RectTransform =
                        {
                            AnchorMin = $"0.04 {rowBot}",
                            AnchorMax = $"0.96 {rowTop}",
                        },
                    }, FramePanel + ".cats", rowName);
                }

                var icon = RemotePng(CategoryImageKey(_catalog.Categories[i].Shortname));
                var hasIcon = !string.IsNullOrEmpty(icon);
                if (hasIcon)
                {
                    AddRawImage(elements, rowName, icon, 0.04f, 0.08f, 0.30f, 0.92f);
                }

                elements.Add(new CuiLabel
                {
                    Text =
                    {
                        Text = _catalog.Categories[i].Display ?? _catalog.Categories[i].Shortname,
                        FontSize = 11,
                        Align = hasIcon ? TextAnchor.MiddleLeft : TextAnchor.MiddleCenter,
                        Color = "1 1 1 1",
                    },
                    RectTransform =
                    {
                        AnchorMin = hasIcon ? "0.34 0" : "0.04 0",
                        AnchorMax = "0.97 1",
                    },
                }, rowName);

                elements.Add(new CuiButton
                {
                    Button = { Color = ColTransparent, Command = $"skinmenu.ui category {i}" },
                    Text = { Text = string.Empty },
                    RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" },
                }, rowName);
            }
        }

        // Scroll-up + scroll-down buttons sitting on the far left of the
        // category column. A thin track between them shows the current
        // scroll position.
        private void BuildCategoryScrollbar(CuiElementContainer elements, EditorState st,
            int total, int visible,
            float left, float right, float top, float bot)
        {
            elements.Add(new CuiPanel
            {
                Image = { Color = ColSlot },
                RectTransform =
                {
                    AnchorMin = Coord(left, bot),
                    AnchorMax = Coord(right, top),
                },
            }, FramePanel, FramePanel + ".scroll");

            var canScroll = total > visible;
            var upCmd = canScroll ? "skinmenu.ui cat.scroll -1" : "";
            var downCmd = canScroll ? "skinmenu.ui cat.scroll 1" : "";

            // Up arrow at the top.
            AddStyledButton(elements, FramePanel + ".scroll", "\u25B2", upCmd,
                0.05f, 0.88f, 0.95f, 0.97f, fontSize: 12, altColor: ColTransparent);
            // Down arrow at the bottom.
            AddStyledButton(elements, FramePanel + ".scroll", "\u25BC", downCmd,
                0.05f, 0.03f, 0.95f, 0.12f, fontSize: 12, altColor: ColTransparent);

            // Track background.
            elements.Add(new CuiPanel
            {
                Image = { Color = "0.10 0.11 0.13 0.9" },
                RectTransform = { AnchorMin = "0.30 0.13", AnchorMax = "0.70 0.87" },
            }, FramePanel + ".scroll");

            // Scroll position indicator (thumb).
            if (canScroll)
            {
                var trackLen = 0.74f; // 0.87 - 0.13
                var thumbLen = trackLen * ((float)visible / total);
                var maxScroll = Math.Max(1, total - visible);
                var posFromTop = (float)st.CategoryScroll / maxScroll;
                var thumbTop = 0.87f - posFromTop * (trackLen - thumbLen);
                var thumbBot = thumbTop - thumbLen;
                elements.Add(new CuiPanel
                {
                    Image = { Color = ColAccent },
                    RectTransform =
                    {
                        AnchorMin = $"0.32 {thumbBot}",
                        AnchorMax = $"0.68 {thumbTop}",
                    },
                }, FramePanel + ".scroll");
            }
        }

        // Right side: 4-column square skin grid with pagination arrows.
        private void BuildSkinGrid(CuiElementContainer elements, CatalogCategory cat,
                                   List<CatalogSkin> skins, EditorState st,
                                   int perPage, int totalPages)
        {
            const float gridLeft = 0.33f;
            const float gridRight = 0.97f;
            const float gridTop = 0.90f;
            const float gridBot = 0.30f;
            const int cols = 4;

            var rowsPerPage = Math.Max(1, perPage / cols);

            var areaWidth = gridRight - gridLeft;
            var cellPitchX = areaWidth / cols;
            // Slot is slightly smaller than the cell to leave padding.
            var slotWidth = cellPitchX * 0.92f;
            var slotHeight = slotWidth * FrameSquareYPerX;
            var cellPitchY = slotHeight / 0.92f;
            var gridHeight = cellPitchY * rowsPerPage;
            var gridStartY = Mathf.Min(gridTop, gridBot + gridHeight + (gridTop - gridBot - gridHeight) * 0.5f);

            var selectedSkin = st.Selection.TryGetValue(cat.Shortname, out var s) ? s : 0UL;
            var startIdx = st.Page * perPage;

            for (var i = 0; i < perPage; i++)
            {
                var idx = startIdx + i;
                if (idx >= skins.Count) break;
                var skin = skins[idx];
                var col = i % cols;
                var row = i / cols;

                var cellCenterX = gridLeft + (col + 0.5f) * cellPitchX;
                var xMin = cellCenterX - slotWidth * 0.5f;
                var xMax = cellCenterX + slotWidth * 0.5f;
                var cellCenterY = gridStartY - (row + 0.5f) * cellPitchY;
                var yMin = cellCenterY - slotHeight * 0.5f;
                var yMax = cellCenterY + slotHeight * 0.5f;

                var slotName = FramePanel + ".slot." + i;
                var isActive = skin.SkinId == selectedSkin;

                elements.Add(new CuiPanel
                {
                    Image = { Color = isActive ? ColAccentSoft : ColSlot },
                    RectTransform = { AnchorMin = Coord(xMin, yMin), AnchorMax = Coord(xMax, yMax) },
                }, FramePanel, slotName);

                var frame = DesignPng(isActive ? "slot_active" : "slot");
                if (!string.IsNullOrEmpty(frame))
                {
                    AddRawImage(elements, slotName, frame, 0f, 0f, 1f, 1f);
                }

                var iconImg = RemotePng(SkinImageKey(cat.Shortname, skin.SkinId));
                if (!string.IsNullOrEmpty(iconImg))
                {
                    AddRawImage(elements, slotName, iconImg, 0.10f, 0.22f, 0.90f, 0.95f);
                }

                elements.Add(new CuiLabel
                {
                    Text =
                    {
                        Text = skin.Name ?? skin.SkinId.ToString(),
                        FontSize = 10, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1",
                    },
                    RectTransform = { AnchorMin = "0 0.02", AnchorMax = "1 0.20" },
                }, slotName);

                elements.Add(new CuiButton
                {
                    Button = { Color = ColTransparent, Command = $"skinmenu.ui pick {cat.Shortname} {skin.SkinId}" },
                    Text = { Text = string.Empty },
                    RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" },
                }, slotName);
            }

            // Pagination arrows live BELOW the action-buttons row
            // (see BuildBottomPager) so they don't sit on top of
            // the grid. The header still shows "page X/Y".
        }

        // IQKits-style pager: absolute-index commands + arrows that
        // dim to 50% alpha when the player can't go further in that
        // direction. The label uses "{current}/<size=10>{max}</size>"
        // so the current page is visually emphasised.
        private void BuildBottomPager(CuiElementContainer elements, EditorState st, int totalPages)
        {
            const float left = 0.33f;
            const float right = 0.97f;
            const float top = 0.135f;
            const float bot = 0.095f;

            var atFirst = st.Page <= 0;
            var atLast = st.Page >= totalPages - 1;

            AddPagerButton(elements, FramePanel, "\u25C0",
                atFirst ? "" : $"skinmenu.ui pageto {st.Page - 1}",
                left, bot, left + 0.05f, top, dimmed: atFirst);
            AddPagerButton(elements, FramePanel, "\u25B6",
                atLast ? "" : $"skinmenu.ui pageto {st.Page + 1}",
                right - 0.05f, bot, right, top, dimmed: atLast);

            elements.Add(new CuiLabel
            {
                Text =
                {
                    Text = $"{st.Page + 1}/<size=10>{totalPages}</size>",
                    FontSize = 16, Align = TextAnchor.MiddleCenter, Color = "0.89 0.85 0.82 1",
                },
                RectTransform = { AnchorMin = Coord(left + 0.06f, bot),
                                  AnchorMax = Coord(right - 0.06f, top) },
            }, FramePanel);
        }

        // Single pager arrow. Dimmed = half-alpha text, transparent
        // button (click is a no-op because the caller passes an
        // empty command).
        private void AddPagerButton(CuiElementContainer elements, string parent,
            string text, string command,
            float xMin, float yMin, float xMax, float yMax, bool dimmed)
        {
            var color = dimmed ? "1 1 1 0.5" : "1 1 1 1";
            elements.Add(new CuiButton
            {
                Button = { Color = ColTransparent, Command = command ?? string.Empty },
                Text = { Text = text, FontSize = 18,
                         Align = TextAnchor.MiddleCenter, Color = color },
                RectTransform =
                {
                    AnchorMin = Coord(xMin, yMin),
                    AnchorMax = Coord(xMax, yMax),
                },
            }, parent);
        }

        // Three buttons below the grid + active-set label.
        private void BuildActionButtons(CuiElementContainer elements, EditorState st)
        {
            var labels = new[] { "Create set", "Save set", "Enable set" };
            var cmds = new[] { "skinmenu.ui create", "skinmenu.ui save", "skinmenu.ui apply" };

            const float left = 0.33f;
            const float right = 0.97f;
            const float top = 0.250f;
            const float bot = 0.180f;
            var width = (right - left) / labels.Length;

            for (var i = 0; i < labels.Length; i++)
            {
                var xMin = left + i * width + 0.005f;
                var xMax = left + (i + 1) * width - 0.005f;
                AddStyledButton(elements, FramePanel, labels[i], cmds[i],
                    xMin, bot, xMax, top, highlighted: true, fontSize: 13);
            }

            var active = string.IsNullOrEmpty(st.EditingSetName) ? "<i>(no active set)</i>" : $"<b>{st.EditingSetName}</b>";
            elements.Add(new CuiLabel
            {
                Text =
                {
                    Text = "Active set: " + active, FontSize = 12,
                    Align = TextAnchor.MiddleCenter, Color = "0.85 0.85 0.85 1",
                },
                RectTransform = { AnchorMin = Coord(left, 0.145f), AnchorMax = Coord(right, 0.175f) },
            }, FramePanel);
        }

        private void BuildFooter(CuiElementContainer elements)
        {
            AddStyledButton(elements, FramePanel, "All sets", "skinmenu.ui sets",
                0.40f, 0.03f, 0.60f, 0.08f, fontSize: 13);
        }

