            elements.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0.65" },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" },
                CursorEnabled = true,
            }, "Overlay", ListPanel);

            elements.Add(new CuiPanel
            {
                Image = { Color = ColPanel },
                RectTransform = { AnchorMin = "0.30 0.20", AnchorMax = "0.70 0.85" },
            }, ListPanel, ListPanel + ".inner");

            elements.Add(new CuiLabel
            {
                Text =
                {
                    Text = "<b>YOUR SKIN SETS</b>", FontSize = 16,
                    Align = TextAnchor.MiddleCenter, Color = "1 1 1 1",
                },
                RectTransform = { AnchorMin = "0 0.92", AnchorMax = "1 0.99" },
            }, ListPanel + ".inner");

            AddStyledButton(elements, ListPanel + ".inner", "X", "skinmenu.ui sets.close",
                0.93f, 0.93f, 0.99f, 0.99f, altColor: ColDanger, fontSize: 13);

            if (data.Sets.Count == 0)
            {
                elements.Add(new CuiLabel
                {
                    Text =
                    {
                        Text = "You have no sets yet. Press <b>Create set</b> in the main menu.",
                        FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "0.85 0.85 0.85 1",
                    },
                    RectTransform = { AnchorMin = "0.05 0.5", AnchorMax = "0.95 0.6" },
                }, ListPanel + ".inner");
            }
            else
            {
                const float top = 0.88f;
                const float rowH = 0.085f;
                var maxRows = Math.Min(9, data.Sets.Count);
